'use client';
import { useRef, useState } from 'react';
import { Dialog, DropdownMenu } from 'radix-ui';
import { Check, ChevronDown, Landmark, LogOut, Plane, Settings, TreePine, UserRound, Utensils, X } from 'lucide-react';
import {explorationInterests,type ExplorationInterest} from '../../content/interests';
import { readingBands } from '../../content/english/chapter';
import { playerInitials, playerName, type PlayerProfile } from '../../lib/atlas/profile';
import {useInterfaceLanguage} from './Bilingual';
import {AdventureRecovery} from './AdventureRecovery';
import type { useAccountProfile } from './useAccountProfile';

type Account = ReturnType<typeof useAccountProfile>;
function Avatar({ profile }: { profile: PlayerProfile }) {
  const [failed, setFailed] = useState<string | null>(null);
  return <span className="account-avatar" aria-hidden="true">{profile.avatarUrl && failed !== profile.avatarUrl
    ? <img src={profile.avatarUrl} alt="" width={36} height={36} referrerPolicy="no-referrer" onError={() => setFailed(profile.avatarUrl)}/>
    : playerInitials(profile.displayName)}</span>;
}

const interestIcons={nature:TreePine,travel:Plane,food:Utensils,culture:Landmark};
function InterestPicker({value,onChange,disabled}:{value:ExplorationInterest[];onChange:(value:ExplorationInterest[])=>void;disabled:boolean}){
 const {t}=useInterfaceLanguage();
 return <fieldset className="exploration-picker" disabled={disabled}><legend>{t('What do you like exploring?','Bạn thích khám phá điều gì?')}</legend><p className="interest-picker-hint">{t('Choose any topics or skip. You can change these in Profile.','Chọn nhiều chủ đề hoặc bỏ qua. Có thể đổi trong Hồ sơ.')}</p><div className="interest-options">{explorationInterests.map(interest=>{const selected=value.includes(interest.id),Icon=interestIcons[interest.id];return <button type="button" key={interest.id} aria-pressed={selected} onClick={()=>onChange(selected?value.filter(id=>id!==interest.id):[...value,interest.id])}><Icon size={20} aria-hidden="true"/><span>{t(interest.en,interest.vi)}</span><span className="interest-check" aria-hidden="true">{selected&&<Check size={13}/>}</span></button>;})}</div></fieldset>;
}

function ProfileForm({ account, onboarding, settings, onDone }: { account: Account; onboarding: boolean; settings: boolean; onDone: () => void }) {
  const {t}=useInterfaceLanguage();
  const profile = account.profile!;
  const [name, setName] = useState(profile.displayName ?? ''), [band, setBand] = useState(profile.readingBand), [vi, setVi] = useState(profile.vietnameseSupport);
  const [interests,setInterests]=useState<ExplorationInterest[]>(profile.interests??[]);
  const [validation, setValidation] = useState(''), [saved, setSaved] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  return <form className="account-form" onSubmit={async event => {
    event.preventDefault(); setSaved(false);
    const parsed = playerName.safeParse(name);
    if (!settings && !parsed.success) { setValidation(t(parsed.error.issues[0].message)); input.current?.focus(); return; }
    setValidation('');
    const interestsChanged=[...interests].sort().join(',')!==[...(profile.interests??[])].sort().join(',');
    const ok = await account.save(settings ? { readingBand: band, vietnameseSupport: vi } : { displayName: parsed.success ? parsed.data : name, ...(interestsChanged ? { interests } : {}) });
    if (ok) { if (onboarding) onDone(); else setSaved(true); }
  }}>
    {!settings && <>{!onboarding&&<div className="account-identity"><Avatar profile={profile}/><p>{t('Your explorer identity','Tên hiển thị trong hành trình của bạn')}</p></div>}<label htmlFor="player-name">{t('Player name','Tên người chơi')}</label><input ref={input} id="player-name" name="displayName" value={name} maxLength={40} autoComplete="nickname" required aria-invalid={!!validation} aria-describedby={`name-hint${validation?' name-error':''}`} disabled={account.saving} onChange={event => { setName(event.target.value); setSaved(false); setValidation(''); }}/><p id="name-hint" className="micro-copy">{t('1–40 characters. You can change this later.','Từ 1–40 ký tự. Có thể sửa lại sau.')}</p>{validation&&<p id="name-error" role="alert">{validation}</p>}<InterestPicker value={interests} disabled={account.saving} onChange={next=>{setInterests(next);setSaved(false);}}/></>}
    {settings && <fieldset disabled={account.saving}><legend>{t('Reading & language support','Bài đọc & hỗ trợ ngôn ngữ')}</legend><label className="account-support"><input type="checkbox" checked={vi} onChange={event => { setVi(event.target.checked); setSaved(false); }}/><span>{t('Vietnamese learning support','Hỗ trợ tiếng Việt trong bài học')}</span></label><label htmlFor="account-reading">{t('Reading target','Mức độ bài đọc')}</label><select id="account-reading" value={band} onChange={event => { setBand(event.target.value as PlayerProfile['readingBand']); setSaved(false); }}>{readingBands.map(value => <option key={value}>{value}</option>)}</select><p className="micro-copy">{t('Choose the text difficulty you want to practise. This is not a proficiency assessment.','Chọn độ khó bài đọc để luyện tập. Đây không phải đánh giá trình độ.')}</p></fieldset>}
    {account.error && <p role="alert" className="account-error">{t(account.error)}</p>}
    {saved && <p role="status" className="account-saved">{t('Saved to your account.','Đã lưu vào tài khoản.')}</p>}
    <button className="play-button purple" disabled={account.saving} type="submit">{account.saving ? t('Saving…','Đang lưu…') : onboarding ? t('Begin my adventure','Bắt đầu khám phá') : t('Save changes','Lưu thay đổi')}</button>
  </form>;
}

export function AccountMenu({ account, busy }: { account: Account; busy: boolean }) {
  const {t}=useInterfaceLanguage();
  const [panel, setPanel] = useState<'profile' | 'settings' | null>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const logout = useRef<HTMLFormElement>(null);
  const profile = account.profile;
  if (!profile?.displayName) return null;
  return <><form ref={logout} action="/auth/logout" method="post" hidden/><DropdownMenu.Root><DropdownMenu.Trigger asChild><button ref={trigger} className="account-trigger" disabled={busy || account.saving} aria-label={`Account: ${profile.displayName}`}><Avatar profile={profile}/><span className="account-player-name">{profile.displayName}</span><ChevronDown size={15}/></button></DropdownMenu.Trigger><DropdownMenu.Portal><DropdownMenu.Content className="account-dropdown" sideOffset={8} align="end"><DropdownMenu.Label className="account-menu-label">{t('Account','Tài khoản')}</DropdownMenu.Label><DropdownMenu.Item onSelect={() => setPanel('profile')}><UserRound size={17}/> {t('Profile','Hồ sơ')}</DropdownMenu.Item><DropdownMenu.Item onSelect={() => setPanel('settings')}><Settings size={17}/> {t('Settings','Cài đặt')}</DropdownMenu.Item><DropdownMenu.Separator/><DropdownMenu.Item onSelect={() => logout.current?.requestSubmit()}><LogOut size={17}/> {t('Sign out','Đăng xuất')}</DropdownMenu.Item></DropdownMenu.Content></DropdownMenu.Portal></DropdownMenu.Root>
    <Dialog.Root open={panel !== null} onOpenChange={open => { if (!open && !account.saving) setPanel(null); }}><Dialog.Portal><Dialog.Overlay className="account-overlay"/><Dialog.Content className="account-dialog" onCloseAutoFocus={event => { event.preventDefault(); trigger.current?.focus(); }} onEscapeKeyDown={event => { if (account.saving) event.preventDefault(); }} onInteractOutside={event => { if (account.saving) event.preventDefault(); }}><Dialog.Title>{panel === 'settings' ? t('Settings','Cài đặt') : t('Profile','Hồ sơ')}</Dialog.Title><Dialog.Description>{panel === 'settings' ? t('Make your learning trail feel right for you.','Điều chỉnh tùy chọn học tập của bạn.') : t('Make your explorer profile your own.','Chọn tên và sở thích cho hành trình của bạn.')}</Dialog.Description><Dialog.Close className="account-close" aria-label={t('Close account panel','Đóng bảng tài khoản')} disabled={account.saving}><X size={21}/></Dialog.Close>{panel && <ProfileForm key={panel} account={account} onboarding={false} settings={panel === 'settings'} onDone={() => setPanel(null)}/>}</Dialog.Content></Dialog.Portal></Dialog.Root>
  </>;
}

export function AccountSetup({ account }: { account: Account }) {
  const {t}=useInterfaceLanguage();
  if (account.loading) return <section className="auth-gate" aria-live="polite"><h1>{t('Getting your profile ready…','Đang tải hồ sơ của bạn…')}</h1></section>;
  if (!account.profile) return <AdventureRecovery code={account.errorCode} retrying={account.loading} onRetry={account.reload} signedIn/>;
  return <section className="auth-gate account-onboarding" aria-labelledby="onboarding-title"><span className="pill purple">{t('WELCOME TO ATLAS','CHÀO MỪNG ĐẾN ATLAS')}</span><h1 id="onboarding-title">{t('What should we call you?','Bạn muốn được gọi là gì?')}</h1><p>{t('Your adventure starts with a name.','Đặt tên để bắt đầu hành trình của bạn.')}</p><ProfileForm account={account} onboarding settings={false} onDone={() => {}}/><form action="/auth/logout" method="post"><button className="quiet-button" disabled={account.saving}>{t('Sign out','Đăng xuất')}</button></form></section>;
}

'use client';
import {useId} from 'react';
import lakeAdvanced from '../../content/learning/lake-advanced.json' with {type:'json'};
import {BookOpen,ExternalLink,FlaskConical,ShieldCheck} from 'lucide-react';
import type {EvidenceClass,EvidenceCitation,LearningCopy,MissionEvidence,VisualEvidence} from '../../content/evidence/types';
import type {ReadingBand} from '../../content/english/chapter';
export function EvidenceCopy({text,vietnamese}:{text:LearningCopy;vietnamese:boolean}){
 return <span className="evidence-copy"><span lang="en">{text.en}</span>{vietnamese&&<span lang="vi">{text.vi}</span>}</span>;
}
const label=(en:string,vi:string):LearningCopy=>({en,vi});
export const evidenceClassLabels:Record<EvidenceClass,LearningCopy>={
 'verified-fact':label('Verified scientific fact','Kiến thức khoa học có nguồn'),
 'real-measurement':label('Real-world measurement','Số đo thực tế'),
 'fictional-scenario':label('Fictional scenario','Tình huống hư cấu'),
 'simulated-data':label('Simulated game data','Dữ liệu trò chơi giả lập'),
 'unconfirmed-hypothesis':label('Not confirmed yet','Chưa được xác nhận'),
 'case-inference':label('Conclusion within this fictional case','Kết luận trong tình huống hư cấu này'),
};
export function EvidenceTag({kind,vietnamese}:{kind:EvidenceClass;vietnamese:boolean}){return <span className={`evidence-tag evidence-${kind}`}><EvidenceCopy text={evidenceClassLabels[kind]} vietnamese={vietnamese}/></span>;}
function Citations({citations,evidence,vietnamese}:{citations:EvidenceCitation[];evidence:MissionEvidence;vietnamese:boolean}){
 return <ul className="claim-citations">{citations.map((c,i)=>{const s=evidence.sources.find(s=>s.id===c.sourceId);return s?<li key={`${c.sourceId}-${i}`}><a href={s.url} target="_blank" rel="noopener noreferrer">{s.organization} · {s.title} <ExternalLink size={12}/></a><small>{c.locator}</small>{c.relationship==='background-only'&&<small><EvidenceCopy text={label('Method/background only; this source did not measure or confirm the game event.','Chỉ hỗ trợ phương pháp/kiến thức nền; nguồn này không đo hay xác nhận sự kiện trong trò chơi.')} vietnamese={vietnamese}/></small>}</li>:null;})}</ul>;
}
export function EvidenceFigure({visual,evidence,vietnamese}:{visual:VisualEvidence;evidence:MissionEvidence;vietnamese:boolean}){
 return <figure className="evidence-figure" data-visual-id={visual.id}>
 {/* SVG contains no externally loaded media; bilingual alt text and an HTML table accompany quantitative charts. */}
 <img src={visual.src} width={720} height={visual.id==='lake-comparison'?460:visual.id==='oxygen-concept'?340:300} alt={vietnamese?`${visual.alt.en} ${visual.alt.vi}`:visual.alt.en} loading="lazy"/>
 <figcaption><EvidenceCopy text={visual.caption} vietnamese={vietnamese}/><details className="visual-credit"><summary><EvidenceCopy text={label('Visual credit & scientific references','Tác giả hình và nguồn khoa học')} vietnamese={vietnamese}/></summary><p>{visual.attribution.creator} · <a href={visual.attribution.licenseUrl} target="_blank" rel="noopener noreferrer">{visual.attribution.license}</a> · <a href={visual.attribution.sourceUrl} target="_blank" rel="noopener noreferrer"><EvidenceCopy text={label('Original local SVG','Tệp SVG gốc của dự án')} vietnamese={vietnamese}/></a></p><p>{visual.attribution.modifications}</p><Citations citations={visual.citations} evidence={evidence} vietnamese={vietnamese}/></details></figcaption>
 </figure>;
}
/** Reusable presentation. Reveal status comes from the caller's server result;
 * this component does not evaluate answers, issue rewards or assign proficiency. */
export function EvidencePanel({evidence,band,vietnamese,revealExplanation=false,measurementsReady=false}:{evidence:MissionEvidence;band:ReadingBand;vietnamese:boolean;revealExplanation?:boolean;measurementsReady?:boolean}){
 const id=useId();
 const visible=evidence.claims.filter(c=>revealExplanation||(c.reveal==='inspection'&&(c.classification!=='simulated-data'||measurementsReady)));
 return <aside className="evidence-panel" aria-labelledby={`${id}-title`} data-evidence-mission={evidence.missionId}>
 <details className="lake-learn-more"><summary><EvidenceCopy text={label('Learn More · the science & sources (optional)','Tìm hiểu thêm · khoa học và nguồn (không bắt buộc)')} vietnamese={vietnamese}/></summary>
 <div className="evidence-panel-heading"><ShieldCheck size={23}/><div><p className="overline">EVIDENCE NOTEBOOK</p><h2 id={`${id}-title`}><EvidenceCopy text={label('What do we actually know?','Chúng ta thực sự biết gì?')} vietnamese={vietnamese}/></h2></div></div>
 <div className="evidence-notice"><FlaskConical size={20}/><div><EvidenceTag kind="fictional-scenario" vietnamese={vietnamese}/><p><EvidenceCopy text={label('Every site, instrument reading and fish response in this mission is fictional. No real-world measurements are used. The scientific concepts below have separate references.','Mọi địa điểm, số đo và phản ứng của cá trong nhiệm vụ này đều là hư cấu. Không sử dụng số đo thực tế. Các khái niệm khoa học có nguồn tham khảo riêng bên dưới.')} vietnamese={vietnamese}/></p></div></div>
 <section className="evidence-claims" aria-label={vietnamese?'Phân loại bằng chứng':'Evidence classifications'}>{visible.map(c=><article key={c.id} data-claim-id={c.id}><EvidenceTag kind={c.classification} vietnamese={vietnamese}/><p><EvidenceCopy text={c.explanation[band]} vietnamese={vietnamese}/></p>{c.provenance&&<details><summary><EvidenceCopy text={label('Origin & limits','Nguồn gốc và giới hạn')} vietnamese={vietnamese}/></summary><p>{c.provenance.origin}</p><p>{c.provenance.method}</p><p>{c.provenance.limitations}</p></details>}<Citations citations={c.citations} evidence={evidence} vietnamese={vietnamese}/></article>)}</section>
 {revealExplanation?<section className="evidence-explanation" aria-label="Visual scientific explanation"><h3><EvidenceCopy text={label('Why this connection is plausible','Vì sao mối liên hệ này hợp lý')} vietnamese={vietnamese}/></h3>{evidence.visuals.filter(v=>v.reveal==='after-attempt').map(v=><EvidenceFigure key={v.id} visual={v} evidence={evidence} vietnamese={vietnamese}/>)}</section>:<p className="evidence-reveal-note"><EvidenceCopy text={label('Inspect, compare and submit your own conclusion first. The scientific explanation opens after a fieldwork attempt; the supporting sources are available now.','Hãy quan sát, so sánh rồi gửi kết luận của bạn trước. Phần giải thích khoa học mở sau một lần nộp nhiệm vụ; bạn có thể đọc nguồn ngay bây giờ.')} vietnamese={vietnamese}/></p>}
 <section className="evidence-vocabulary"><h3><BookOpen size={18}/> <EvidenceCopy text={label('Words for this investigation','Từ vựng cho cuộc điều tra')} vietnamese={vietnamese}/></h3>{evidence.vocabulary.map(v=><details key={v.word}><summary lang="en">{v.word}</summary><p><EvidenceCopy text={v.meaning} vietnamese={vietnamese}/></p><p><em><EvidenceCopy text={v.example} vietnamese={vietnamese}/></em></p><Citations citations={evidence.claims.filter(c=>v.claimIds.includes(c.id)).flatMap(c=>c.citations)} evidence={evidence} vietnamese={vietnamese}/></details>)}</section>
 <details className="evidence-sources"><summary><EvidenceCopy text={label('Open the source library · USGS & EPA','Mở thư viện nguồn · USGS và EPA')} vietnamese={vietnamese}/></summary><p><EvidenceCopy text={label('Links open the original pages in a new tab. These sources support general science and methods, not the fictional values.','Liên kết mở trang gốc trong tab mới. Nguồn hỗ trợ khoa học và phương pháp chung, không xác nhận số liệu hư cấu.')} vietnamese={vietnamese}/></p>{evidence.sources.map(s=><article key={s.id}><strong>{s.organization}</strong><a href={s.url} target="_blank" rel="noopener noreferrer">{s.title} <ExternalLink size={14}/></a><span className="source-url">{s.url}</span><dl><dt><EvidenceCopy text={label('Publication date','Ngày xuất bản')} vietnamese={vietnamese}/></dt><dd>{s.publishedAt??(vietnamese?'Không nêu ngày xuất bản gốc':'Original date not stated')}</dd>{s.updatedAt&&<><dt><EvidenceCopy text={label('Page updated','Trang cập nhật')} vietnamese={vietnamese}/></dt><dd>{s.updatedAt}</dd></>}<dt><EvidenceCopy text={label('Last verified','Kiểm tra nguồn gần nhất')} vietnamese={vietnamese}/></dt><dd>{s.lastVerifiedAt}</dd></dl><p>{s.dateNote}</p><p>{s.verificationNote}</p></article>)}</details>
 <details className="lake-original-notes"><summary><EvidenceCopy text={label('Original technical field notes','Ghi chú chuyên sâu gốc')} vietnamese={vietnamese}/></summary><p>{lakeAdvanced.mission.narrative}</p>{lakeAdvanced.mission.challenge.observations.map(o=><p key={o.id}><strong>{o.title}: </strong>{o.detail}</p>)}<p>{lakeAdvanced.variants[band].passage}</p>{vietnamese&&<p lang="vi">{lakeAdvanced.variants[band].vi}</p>}</details></details>
 </aside>;
}

'use client';
import {useState} from 'react';
import {BookOpen,Search,ImageIcon} from 'lucide-react';
import type {EnglishLesson,GlossaryEntry} from '../../content/english/chapter';
import {wordDetails} from '../../content/english/word-details';
import {Pronunciation,SaveWordButton} from './SavedVocabulary';
import {Bilingual} from './Bilingual';
function Example({entry}:{entry:GlossaryEntry}){
 const at=entry.example.toLowerCase().indexOf(entry.word.toLowerCase());
 return <p lang="en">{at<0?entry.example:<>{entry.example.slice(0,at)}<mark>{entry.example.slice(at,at+entry.word.length)}</mark>{entry.example.slice(at+entry.word.length)}</>}</p>;
}
export function VocabularyNotebook({lessons,vietnamese:vi}:{lessons:readonly EnglishLesson[];vietnamese:boolean}){
 const [query,setQuery]=useState('');
 const normalized=query.trim().toLocaleLowerCase('vi');
 const groups=lessons.map(lesson=>({lesson,entries:lesson.glossary.filter(entry=>`${entry.word} ${vi?entry.meaning:''}`.toLocaleLowerCase('vi').includes(normalized))})).filter(group=>group.entries.length);
 const count=groups.reduce((sum,group)=>sum+group.entries.length,0);
 return <section className="vocabulary-notebook" aria-labelledby="encountered-words-title">
 <div className="vocabulary-heading"><div><span className="vocabulary-eyebrow"><BookOpen size={16}/>{vi?'YOUR WORD COLLECTION · BỘ TỪ VỰNG':'YOUR WORD COLLECTION'}</span><h2 id="encountered-words-title"><Bilingual text="Words you’ve encountered"/></h2><p>{vi?'Ôn từ qua hình ảnh, phiên âm và câu trong nhiệm vụ.':'Revisit each word through a visual, its pronunciation and a mission example.'}</p></div><label className="vocabulary-search"><Search size={18}/><span className="sr-only">{vi?'Tìm từ tiếng Anh hoặc nghĩa tiếng Việt':'Search encountered words'}</span><input type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder={vi?'Tìm từ hoặc nghĩa…':'Find a word…'}/></label></div>
 <p className="vocabulary-result-count" role="status">{count} {vi?'từ trong sổ tay':'words in your notebook'}</p>
 {!count&&<p className="vocabulary-empty">{lessons.length?(vi?'Chưa tìm thấy từ phù hợp. Thử một từ khác.':'No matching words. Try another search.'):(vi?'Luyện một field note để mở bộ từ vựng của nhiệm vụ.':'Practise a field note to discover its word collection.')}</p>}
 {groups.map(({lesson,entries})=><section className="vocabulary-group" key={lesson.id} aria-label={lesson.title}><h3><Bilingual text={lesson.title}/><span>{entries.length} {vi?'từ':'words'}</span></h3><div className="vocabulary-card-grid">{entries.map(entry=>{const detail=wordDetails[entry.word];return <article className="vocabulary-study-card" key={entry.word}>
 {detail&&<figure><img src={detail.image} srcSet={detail.scene?`${detail.image} 480w, ${detail.image.replace("-480.webp","-960.webp")} 960w`:undefined} sizes={detail.scene?"(max-width: 650px) calc(100vw - 64px), (min-width: 1500px) 400px, 540px":undefined} alt={detail.alt} loading="lazy" decoding="async" width={360} height={180} style={{objectPosition:detail.position}}/><figcaption><ImageIcon size={12}/>{detail.scene?(vi?'Tranh bối cảnh ATLAS':'ATLAS scene artwork'):(vi?'Minh họa khái niệm':'Concept illustration')}</figcaption></figure>}
 <div className="vocabulary-card-body"><div className="vocabulary-word-heading"><h4 lang="en">{entry.word}</h4>{detail&&<span lang="en">{detail.partOfSpeech}</span>}</div><Pronunciation word={entry.word}/>{vi&&<p className="vocabulary-meaning" lang="vi">{entry.meaning}</p>}{detail&&<p className="vocabulary-definition" lang="en">{detail.definition}</p>}
 <div className="vocabulary-example"><span>{vi?'IN CONTEXT · VÍ DỤ':'IN CONTEXT'}</span><Example entry={entry}/>{vi&&<details><summary lang="vi">Xem nghĩa câu & giải thích</summary><p lang="vi">{entry.exampleVi}</p><p lang="vi">{entry.explanation}</p></details>}</div>
 {detail&&<p className="vocabulary-chunk"><span>{vi?'Cụm nên nhớ':'Useful chunk'}</span><strong lang="en">{detail.chunk}</strong></p>}
 <SaveWordButton lessonId={lesson.id} version={lesson.version} word={entry.word}/></div></article>;})}</div></section>)}
 <details className="vocabulary-credits"><summary>{vi?'Nguồn phiên âm & hình minh họa':'Pronunciation & visual credits'}</summary><p>{vi?'IPA US/UK: Cambridge Dictionary; mở “IPA source” ở từng thẻ để đối chiếu và nghe bản thu tại nguồn. Côn trùng dùng dạng số nhiều của insect.':'US/UK IPA: Cambridge Dictionary. Open each card’s IPA source to check the transcription and hear the source recording. Insects uses the plural form of insect.'}</p><p>{vi?'Tranh rừng và hồ do chủ dự án cung cấp; minh họa khái niệm được vẽ riêng cho ATLAS. Đây là học liệu minh họa, không phải ảnh hay số đo thực địa.':'Forest and lake artwork supplied by the project owner; concept diagrams created for ATLAS. These learning visuals are not field photographs or real-world measurements.'}</p><p>{vi?'Câu ví dụ và giải nghĩa tiếng Việt giữ nguyên học liệu hiện có, đang chờ giáo viên thẩm định.':'Examples and Vietnamese explanations retain the existing lesson content, pending educator review.'}</p></details>
 </section>;
}

'use client';
import {useInterfaceLanguage} from '../Bilingual';
import {useEffect,useRef,useState} from 'react';
import {ArrowLeft,ArrowRight,ArrowUp,ArrowDown,BookOpen,Check,MapPin,MessageCircle,Search,X,RefreshCw} from 'lucide-react';
import type {CountryPack,TravelEncounter,EncounterProgress,TravelAction,Copy,Hotspot} from '../../../content/travel/types';
import type {ReadingBand} from '../../../content/english/chapter';
import {copy} from '../../../content/travel/japan';
import {TravelCopy} from './TravelCopy';
import {SaveWordButton,Pronunciation} from '../SavedVocabulary';
