 {mode==='journey'&&<section className="travel-arrival" aria-live="polite"><span className="arrival-orbit"><Plane size={52}/></span><p className="travel-overline">A NEW CHAPTER BEGINS</p><h1 ref={heading} tabIndex={-1}><TravelCopy text={copy(`Next stop: ${pack.destinations[0].name.en}`,`Điểm đến tiếp theo: ${pack.destinations[0].name.vi}`)} vi={vi}/></h1><p><TravelCopy text={copy('Pack your curiosity. Your English is coming with you.','Mang theo sự tò mò. Tiếng Anh sẽ đồng hành cùng bạn.')} vi={vi}/></p></section>}
